CREATE TABLE `notificaciones` (
  `id_notificacion` int NOT NULL AUTO_INCREMENT,
  `id_usuario` int NOT NULL,
  `id_alumno` int DEFAULT NULL,
  `titulo` varchar(255) DEFAULT NULL,
  `mensaje` text,
  `fecha` datetime DEFAULT NULL,
  `leida` tinyint(1) DEFAULT '0',
  `rol` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id_notificacion`),
  KEY `id_usuario` (`id_usuario`),
  KEY `idx_notificaciones_id_alumno` (`id_alumno`),
  CONSTRAINT `fk_notificaciones_alumno` FOREIGN KEY (`id_alumno`) REFERENCES `alumnos` (`id_alumno`),
  CONSTRAINT `notificaciones_ibfk_1` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id_usuario`)
) ENGINE=InnoDB AUTO_INCREMENT=21098 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
